#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDspiCore: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = DspiCore

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> DspiCore {
        return DspiCore(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: DspiCore) -> UnsafeMutableRawPointer {
