        /**
         * Receive overflows.
         */rxOverflow: UInt32, 
        /**
         * Receive timeouts.
         */rxTimeout: UInt32, 
        /**
         * Data sequence errors.
         */dataSeq: UInt32) {
        self.total = total
        self.crc = crc
        self.bitstuff = bitstuff
        self.rxOverflow = rxOverflow
        self.rxTimeout = rxTimeout
        self.dataSeq = dataSeq
    }
}

